import type { Metadata } from 'next'
import { notFound } from 'next/navigation'
import { getPost, getPostComments, getPosts } from '@/lib/posts'
import { BackButton } from './back-button'

// Replaces `fallback: 'blocking'`: ids that were not prerendered by
// `generateStaticParams` are rendered on demand and then cached.
export const dynamicParams = true

// Replaces `getStaticPaths`.
export async function generateStaticParams() {
  const posts = await getPosts()

  return posts.slice(0, 10).map((post) => ({
    id: post.id.toString(),
  }))
}

// Replaces the `<Head>` tags that used to be rendered by the page component.
export async function generateMetadata({
  params,
}: PageProps<'/blog/[id]'>): Promise<Metadata> {
  const { id } = await params
  const post = await getPost(id)

  // The page component calls `notFound()` for this id, and `not-found.tsx`
  // supplies the metadata for that response.
  if (!post) {
    return {}
  }

  const description = post.body.substring(0, 160)

  return {
    title: post.title,
    description,
    openGraph: {
      title: post.title,
      description,
    },
  }
}

export default async function BlogPostPage({ params }: PageProps<'/blog/[id]'>) {
  const { id } = await params
  const [post, comments] = await Promise.all([
    getPost(id),
    getPostComments(id),
  ])

  // Replaces `return { notFound: true }` from `getStaticProps`.
  if (!post) {
    notFound()
  }

  return (
    <article>
      <BackButton />

      <h1>{post.title}</h1>
      <p>{post.body}</p>

      <h2>Comments ({comments.length})</h2>
      <div className="comments">
        {comments.map((comment) => (
          <div key={comment.id} className="comment">
            <h3>{comment.name}</h3>
            <p>{comment.body}</p>
            <small>By: {comment.email}</small>
          </div>
        ))}
      </div>
    </article>
  )
}

import type { Metadata } from 'next'
import { headers } from 'next/headers'
import Link from 'next/link'
import { getRecentPosts } from '@/lib/posts'
import { ViewAllPostsButton } from './view-all-posts-button'

export const metadata: Metadata = {
  // A `title.template` from a layout does not apply to a page in the same route
  // segment, so the root layout's `%s - My Blog` suffix is spelled out here.
  title: 'Home - My Blog',
  description: 'Welcome to my blog homepage',
  openGraph: {
    title: 'Home - My Blog',
  },
}

export default async function HomePage() {
  // `getServerSideProps({ req })` is replaced by the async `headers()` API.
  const requestHeaders = await headers()
  const userAgent = requestHeaders.get('user-agent') ?? ''
  const posts = await getRecentPosts()
  const timestamp = new Date().toISOString()

  return (
    <div>
      <h1>Welcome to My Blog</h1>
      <p>Server-side rendered at: {timestamp}</p>
      <p>Your user agent: {userAgent}</p>

      <h2>Recent Posts</h2>
      <ul>
        {posts.map((post) => (
          <li key={post.id}>
            <Link href={`/blog/${post.id}`}>{post.title}</Link>
          </li>
        ))}
      </ul>

      <ViewAllPostsButton />
    </div>
  )
}

const API_BASE = 'https://jsonplaceholder.typicode.com'

export interface Post {
  id: number
  userId: number
  title: string
  body: string
}

export interface PostComment {
  id: number
  postId: number
  name: string
  email: string
  body: string
}

/**
 * Uncached read, equivalent to the old `getServerSideProps` behavior: the data
 * is fetched from the source on every request.
 */
export async function getRecentPosts(limit = 5): Promise<Post[]> {
  const res = await fetch(`${API_BASE}/posts?_limit=${limit}`, {
    cache: 'no-store',
  })

  if (!res.ok) {
    throw new Error(`Failed to fetch recent posts (${res.status})`)
  }

  return res.json()
}

/**
 * Cached read revalidated every 60 seconds, equivalent to the old
 * `getStaticProps` + `revalidate: 60` (ISR).
 */
export async function getPosts(): Promise<Post[]> {
  const res = await fetch(`${API_BASE}/posts`, {
    next: { revalidate: 60 },
  })

  if (!res.ok) {
    throw new Error(`Failed to fetch posts (${res.status})`)
  }

  return res.json()
}

/**
 * Cached read revalidated every 5 minutes, equivalent to the old
 * `getStaticProps` + `revalidate: 300`. Returns `null` when the post does not
 * exist so callers can render the not-found UI.
 */
export async function getPost(id: string): Promise<Post | null> {
  const res = await fetch(`${API_BASE}/posts/${id}`, {
    next: { revalidate: 300 },
  })

  if (!res.ok) {
    return null
  }

  const post: Partial<Post> = await res.json()

  // The upstream API answers unknown ids with an empty object.
  return typeof post.id === 'number' ? (post as Post) : null
}

export async function getPostComments(id: string): Promise<PostComment[]> {
  const res = await fetch(`${API_BASE}/posts/${id}/comments`, {
    next: { revalidate: 300 },
  })

  if (!res.ok) {
    return []
  }

  return res.json()
}

