import type { NextRequest } from 'next/server'
import type { ApiPost } from '../route'

interface UpdatePostBody {
  title?: unknown
  content?: unknown
}

export async function GET(
  request: NextRequest,
  ctx: RouteContext<'/api/posts/[id]'>
) {
  // `params` is a promise in Next.js 16.
  const { id } = await ctx.params

  // Simulate fetching a single post
  const post: ApiPost = {
    id: Number.parseInt(id, 10),
    title: `Post ${id}`,
    content: `This is the content for post ${id}`,
    createdAt: new Date().toISOString(),
  }

  return Response.json(post)
}

export async function PUT(
  request: NextRequest,
  ctx: RouteContext<'/api/posts/[id]'>
) {
  const { id } = await ctx.params

  let body: UpdatePostBody = {}
  try {
    body = await request.json()
  } catch {
    // Keep the previous behavior of falling back to defaults for an empty body.
  }

  const { title, content } = body

  // Simulate updating a post
  const updatedPost: ApiPost = {
    id: Number.parseInt(id, 10),
    title: typeof title === 'string' && title ? title : `Post ${id}`,
    content:
      typeof content === 'string' && content
        ? content
        : `Updated content for post ${id}`,
    updatedAt: new Date().toISOString(),
  }

  return Response.json(updatedPost)
}

export async function DELETE(
  request: NextRequest,
  ctx: RouteContext<'/api/posts/[id]'>
) {
  const { id } = await ctx.params

  // Simulate deleting a post
  return Response.json({ message: `Post ${id} deleted successfully` })
}

// Methods that are not exported are answered by Next.js with a 405 and the
// appropriate `Allow` header, so the manual fallback is no longer needed.
